import{visualState105,setVisual105,watchVisual105}from'./visual-settings105.js?v=105';
export class GameShell105{
 constructor(doc=document,win=window){this.doc=doc;this.win=win;this.wasRunning=false;this.$=id=>doc.getElementById(id);doc.body.classList.add('game105');const bar=doc.createElement('section');bar.id='g105-context';bar.setAttribute('aria-label','Experiencia y accesos rápidos');bar.innerHTML='<span><b id="g105-section">CENTRO DE OPERACIONES</b><output id="g105-live"></output></span><div class="g105-context-actions"><button id="g105-run" hidden>Iniciar recorrido</button><button id="g105-hud" title="Mostrar indicadores, clima y ajustes del escenario" aria-pressed="false">HUD ampliado</button><button id="g105-fullscreen">Pantalla completa</button><button id="g105-options">Ajustes</button><button id="g105-pause-button">Pausa · Esc</button></div>';doc.querySelector('.experience-nav').after(bar);
 const pause=doc.createElement('dialog');pause.id='g105-pause';pause.setAttribute('aria-labelledby','g105-pause-title');pause.innerHTML='<span class="g105-modal-kicker">METRO · OPERACIONES</span><h2 id="g105-pause-title">En pausa.</h2><p class="g105-muted">Tu recorrido espera. Continúa cuando estés listo.</p><div class="g105-menu-stack"><button id="g105-resume">Continuar experiencia</button><button id="g105-pause-options">Ajustes de imagen e interfaz</button><button id="g105-home">Volver al menú principal</button></div><small class="g105-muted">Esc · Continuar</small>';doc.body.append(pause);
 const settings=doc.createElement('dialog');settings.id='g105-settings';settings.setAttribute('aria-labelledby','g105-settings-title');settings.innerHTML='<span class="g105-modal-kicker">CONFIGURACIÓN VISUAL</span><h2 id="g105-settings-title">A tu manera.</h2><div class="g105-setting-row"><label for="g105-quality">Calidad de imagen<small>Materiales detallados en todos los modos; sombras del banco según tu equipo.</small></label><select id="g105-quality"><option value="performance">Rendimiento</option><option value="balanced">Equilibrado</option><option value="cinematic">Cinematográfico</option></select></div><div class="g105-setting-row"><label for="g105-exposure">Exposición<small>Ajusta la luminosidad del render 3D.</small></label><input id="g105-exposure" aria-label="Exposición" type="range" min="0.75" max="1.2" step="0.05" value="1"></div><div class="g105-setting-row"><label for="g105-detail">Instrumentos en pantalla<small>El HUD compacto da más espacio al escenario.</small></label><select id="g105-detail"><option value="compact">Compacto</option><option value="extended">Ampliado</option></select></div><div class="g105-setting-row"><label for="g105-vignette">Encuadre cinematográfico<small>Oscurecimiento suave de los bordes del escenario.</small></label><input id="g105-vignette" type="checkbox" checked></div><p class="g105-muted">La resolución se adapta si el render se ralentiza. La vista de la red conserva su límite gráfico de 30 Hz; el taller y el mantenimiento admiten hasta 60 Hz.</p><div class="g105-dialog-foot"><button id="g105-settings-close">Volver</button></div>';doc.body.append(settings);
 const options=doc.createElement('button');options.id='g105-header-options';options.textContent='Ajustes';doc.querySelector('.header-right').append(options);const career=doc.createElement('div');career.className='g105-career';career.innerHTML='<span>PROGRESO DE TALLER</span><span class="g105-career-track"><i id="g105-career-fill"></i></span><b id="g105-career-count">0 / 4</b>';doc.querySelector('.game-home-copy').append(career);const line=doc.createElement('div');line.className='g105-loader-line';line.setAttribute('aria-hidden','true');this.$('game-loading-message').after(line);
 this.$('g105-fullscreen').onclick=async()=>{try{if(this.doc.fullscreenElement)await this.doc.exitFullscreen();else if(this.doc.documentElement?.requestFullscreen)await this.doc.documentElement.requestFullscreen();else this.$('g105-fullscreen').textContent='Usa F11';}catch{this.$('g105-fullscreen').textContent='Usa F11';}};this.$('g105-run').onclick=()=>{this.$('play').click();this.status();};this.$('g105-pause-button').onclick=()=>this.pause();this.$('g105-resume').onclick=()=>this.resume();this.$('g105-home').onclick=()=>{this.closePause(false);this.win.metroGame?.home();};for(const id of['g105-options','g105-header-options','g105-pause-options'])this.$(id).onclick=()=>this.openSettings();this.$('g105-settings-close').onclick=()=>this.$('g105-settings').close();settings.addEventListener('close',()=>{this.syncOverlay();if(this.settingsWasRunning&&!this.win.metroViewState?.()?.running&&this.doc.body.dataset.gameScreen==='simulation')this.$('play').click();this.settingsWasRunning=false;});this.$('g105-hud').onclick=()=>setVisual105({hud:visualState105().hud==='compact'?'extended':'compact'});this.$('g105-quality').onchange=e=>setVisual105({quality:e.target.value});this.$('g105-exposure').oninput=e=>setVisual105({exposure:Number(e.target.value)});this.$('g105-detail').onchange=e=>setVisual105({hud:e.target.value});this.$('g105-vignette').onchange=e=>setVisual105({vignette:e.target.checked});pause.addEventListener('close',()=>this.syncOverlay());pause.addEventListener('cancel',e=>{e.preventDefault();this.resume();});
 win.addEventListener('keydown',e=>{if(e.key!=='Escape'||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;if((!this.doc.querySelector('dialog[open]')&&this.win.metroMission117?.dismissOverlay())||this.win.metroSimulation106?.dismissOverlay()){e.preventDefault();e.stopImmediatePropagation();return;}if(this.$('g105-settings').open){e.preventDefault();e.stopImmediatePropagation();this.$('g105-settings').close();return;}if(this.doc.querySelector('dialog[open]')&&!pause.open)return;if(this.doc.body.dataset.gameScreen==='maintenance'&&(win.metroRepair?.state.selectedItem||win.metroRepair?.state.toolMotion))return;e.preventDefault();e.stopImmediatePropagation();pause.open?this.resume():this.pause();},true);
 watchVisual105(s=>this.apply(s));this.apply(visualState105());new MutationObserver(()=>this.status()).observe(doc.body,{attributes:true,attributeFilter:['data-game-screen','data-driving']});win.addEventListener('metro-repair-completed',()=>this.status());win.addEventListener('metro-ready',()=>this.status());this.status();this.timer=win.setInterval(()=>{if(!doc.hidden&&doc.body.dataset.gameScreen==='simulation')this.status();},500);
 }
 syncOverlay(){const active=Boolean(this.$('g105-pause').open||this.$('g105-settings').open),was=this.doc.body.dataset.pause105==='true';this.doc.body.dataset.pause105=String(active);if(active&&!was)this.pauseAt=performance.now();if(!active&&was)this.win.dispatchEvent(new CustomEvent('metro-resume105',{detail:{elapsed:performance.now()-(this.pauseAt||performance.now())}}));}
 pause(){if(this.$('g105-pause').open)return;const current=this.win.metroViewState?.();this.wasRunning=Boolean(this.doc.body.dataset.gameScreen==='simulation'&&current?.running);if(this.wasRunning)this.$('play').click();this.$('g105-pause').showModal();this.syncOverlay();}
 closePause(resume=true){this.$('g105-pause').close();if(resume&&this.wasRunning&&!this.win.metroViewState?.()?.running&&this.doc.body.dataset.gameScreen==='simulation')this.$('play').click();this.wasRunning=false;}
 resume(){this.closePause(true);}
 openSettings(){if(this.$('g105-settings').open)return;this.settingsWasRunning=Boolean(!this.$('g105-pause').open&&this.doc.body.dataset.gameScreen==='simulation'&&this.win.metroViewState?.()?.running);if(this.settingsWasRunning)this.$('play').click();this.$('g105-settings').showModal();this.syncOverlay();}
 apply(s){this.doc.body.dataset.hud105=s.hud;this.doc.body.dataset.vignette105=String(s.vignette);this.$('g105-hud').setAttribute('aria-pressed',String(s.hud==='extended'));this.$('g105-hud').textContent=s.hud==='compact'?'HUD ampliado':'HUD compacto';this.$('g105-quality').value=s.quality;this.$('g105-exposure').value=s.exposure;this.$('g105-detail').value=s.hud;this.$('g105-vignette').checked=s.vignette;this.win.dispatchEvent(new Event('resize'));}
 status(){const screen=this.doc.body.dataset.gameScreen;this.$('g105-run').hidden=screen!=='simulation';this.$('g105-run').textContent=this.win.metroViewState?.()?.running?'Pausar recorrido':'Iniciar recorrido';const names={home:'CENTRO DE OPERACIONES',depot:'FLOTA / SELECCIONAR TREN',detail:'INSPECCIÓN / EXPLORAR MODELO',maintenance:'TALLER / MISIÓN ACTIVA',loading:'PREPARANDO EXPERIENCIA',simulation:this.doc.body.dataset.driving==='true'?'CONDUCCIÓN / CABINA':'RED / OBSERVACIÓN'};this.$('g105-section').textContent=names[screen]||'METRO CDMX';let records={};try{records=JSON.parse(this.win.localStorage?.getItem('metro-repairs82')||'{}');}catch{}const done=['doors','ventilation','running','electrical'].filter(k=>records[k]).length;this.$('g105-career-count').textContent=done+' / 4';this.$('g105-career-fill').style.width=(done*25)+'%';const s=this.win.metroViewState?.(),train=s?.engine?.trains.find(t=>t.id===s.selectedTrain);this.$('g105-live').textContent=screen==='simulation'&&train?`L${train.line} · ${train.model} · ${Math.round(train.speed*3.6)} km/h · ${s.engine.lines[train.line].stations[train.target].nombre}${s.engine.weather==='rain'?' · LLUVIA':''}`:screen==='maintenance'?'Selecciona una misión · interactúa sobre las piezas':screen==='depot'?'NM-22 / NM-79 / MP-82 · selecciona un convoy':'Geometría 3D · cámaras libres · inspección de componentes';}
}
if(typeof document!=='undefined'&&document.getElementById('game-home'))window.metroGameShell105=new GameShell105();
